class Solution {
public:
    bool validUtf8(vector<int>& data) {
        int n = (int)data.size();
        int i = 0;
        while (i < n) {
            int b = data[i] & 0xFF;
            int numBytes;
            if ((b & 0x80) == 0x00) {
                // 0xxxxxxx
                numBytes = 1;
            } else if ((b & 0xE0) == 0xC0) {
                // 110xxxxx
                numBytes = 2;
            } else if ((b & 0xF0) == 0xE0) {
                // 1110xxxx
                numBytes = 3;
            } else if ((b & 0xF8) == 0xF0) {
                // 11110xxx
                numBytes = 4;
            } else {
                // 10xxxxxx as leader, or 11111xxx, etc.
                return false;
            }
            for (int j = 1; j < numBytes; j++) {
                if (i + j >= n) return false;
                int c = data[i + j] & 0xFF;
                if ((c & 0xC0) != 0x80) return false;
            }
            i += numBytes;
        }
        return true;
    }
};
